            int m = reader.nextInt();

            if (m == 1)
                writer.println(n - 1);
            else
                writer.println((long) n * (m - 1));
        }
    }

    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String[] readLineArray() {
            try {
                return reader.readLine().trim().split("\\s+");
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int[] nextIntArray() {
            String[] tokens = readLineArray();
            int[] result = new int[tokens.length];
            for (int i = 0; i < tokens.length; i++) {
                result[i] = Integer.parseInt(tokens[i]);
            }
            return result;
        }

        public long[] nextLongArray() {
            String[] tokens = readLineArray();
            long[] result = new long[tokens.length];
            for (int i = 0; i < tokens.length; i++) {
                result[i] = Long.parseLong(tokens[i]);
            }
            return result;
        }

        public double[] nextDoubleArray() {
            String[] tokens = readLineArray();
            double[] result = new double[tokens.length];
            for (int i = 0; i < tokens.length; i++) {
                result[i] = Double.parseDouble(tokens[i]);
            }
            return result;
        }
    }

    static class FastPrinter {
        private final PrintWriter writer;

        public FastPrinter(OutputStream out) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        public void print(Object... objects) {
            StringBuilder sb = new StringBuilder();
            for (Object obj : objects) {
                sb.append(obj).append(" ");
            }
            writer.print(sb.toString().trim());
        }

        public void println(Object... objects) {
            StringBuilder sb = new StringBuilder();
            for (Object obj : objects) {
                sb.append(obj).append(" ");
            }
            writer.println(sb.toString().trim());
        }

        public void close() {
            writer.close();
        }
    }
}

